        [13] = "J'ai repris la route {at}, portant la Lumière comme l'Église l'a toujours enseigné, un abri à prêter plutôt qu'une bannière à agiter.",
        [14] = "[[Northshire Valley]] était loin derrière moi désormais, tout comme $gle débutant:la débutante; qui en était $gsorti:sortie; pour la première fois. J'ai repris la route {at}.",
        [15] = "La nuit était tombée {at} quand je me suis $gmis:mise; en route, et ma curiosité pour la contrée pouvait attendre le jour.",
        [16] = "Le roi avait disparu, mais il fallait toujours parcourir les routes et faire les courses, et je me suis $gmis:mise; en route {at} pour prendre ma part.",
        [17] = "Rien de ce qui vaut la peine n'est gratuit, sauf l'opinion des autres, et je me suis $gmis:mise; au travail {at} pour gagner le reste.",
        [18] = "Une nouvelle journée de travail m'attendait {at}, et je m'y suis $gattelé:attelée; comme un boutiquier relève ses volets, sans en faire tout un discours.",
        [19] = "L'heure appartenait aux chouettes et aux veilleurs plutôt qu'aux honnêtes voyageurs, mais j'étais debout {at} quand même.",
        [20] = "Je me suis $gmis:mise; en route à une heure respectable {at}, comme tout honnête travailleur, en espérant que la journée me rendrait la politesse.",
        [21] = "Mon peuple avait relevé une cité entière de ses décombres, et à côté de cela, le travail qui m'attendait {at} semblait assez modeste pour s'y mettre de bon cœur.",
        [22] = "J'ai poursuivi {at}, $gun invité:une invitée; dans un pays aux usages bien à lui, et j'ai gardé les habitudes de chez moi pour moi jusqu'à savoir lesquelles seraient bienvenues.",
        [23] = "{where} était une terre que mon peuple avait bâtie, cultivée et défendue depuis des générations, et cela m'a plus $grassuré:rassurée; que je ne l'aurais cru.",
        [24] = "Le courage serait strictement réservé aux moments où il serait nécessaire, ai-je décidé {at}, et je me suis $gmis:mise; en route.",
        [25] = "J'ai continué {at} avec deux mains de bonne volonté et les doutes habituels sur le reste de ma personne.",
        [26] = "J'ai poursuivi {at}, en démêlant ce que j'avais entendu dire du vaste monde de ce que j'y trouvais.",
      },
      ["rest"] = {
