        [5] = "J'avais plus de tendresse pour les gens installés que je n'en avais en partant, et je me suis $garrêté:arrêtée; {at} pour être $gl'un:l'une; d'eux un moment.",
        [6] = "Mes pensées sont allées aux gens encore inquiets du pain du lendemain quand je me suis $ginstallé:installée; {at}.",
        [7] = "{at}, le calme était aussi simple qu'un souper à [[Goldshire]], et j'en étais $gheureux:heureuse;.",
        [8] = "Les exigences du jour se sont réduites {at} à la simple question de rester sur place.",
        [9] = "Pour une fois, j'ai laissé les ennuis des autres attendre que je sois $gprêt:prête;, et je me suis $garrêté:arrêtée; {at}.",
        [10] = "Le feu {at} était une compagnie suffisante, et je suis $gresté:restée; longtemps avec lui.",
        [11] = "Un peu de repos {at} était la seule récompense que je voulais à ce moment-là, et je l'ai prise sans m'excuser.",
        [12] = "Je me suis $greposé:reposée; {at}, en pensant à tous ceux que les guerres n'avaient jamais laissés vieillir, bien $gdécidé:décidée; à ne pas les rejoindre.",
        [13] = "Je me suis $greposé:reposée; {at}, et la route pouvait garder ses paysages jusqu'à ce que j'en aie de nouveau envie.",
        [14] = "Le dernier travail était derrière moi, et je me suis $greposé:reposée; {at} sans guetter le suivant.",
        [15] = "Je me suis $greposé:reposée; {at} et j'ai laissé redescendre mes épaules, que la journée avait remontées jusqu'aux oreilles.",
        [16] = "Je me suis $ginstallé:installée; près du feu {at}, et pendant un moment mon seul devoir a été de rester au chaud et de me tenir à l'écart des ennuis, ce que j'ai fait admirablement.",
