        [5] = "Quelque chose a bien failli m'ôter cette vie, et je me découvre en colère, ce qui est meilleur signe que la peur.",
        [6] = "J'ai gardé mon sang-froid sous terre à peu près aussi bien que partout ailleurs, c'est-à-dire mieux que je ne le craignais et moins bien que je ne le voudrais.",
        [7] = "Sans seconde résurrection sur laquelle compter, frôler ainsi la fin m'a $grendu:rendue; plus $gprudent:prudente; que je ne l'ai jamais été.",
      },
      ["d-foes"] = {
        [1] = "J'ai mis fin à {foes}, et j'ai considéré l'affaire comme close sans autre cérémonie.",
        [2] = "De tout ce que j'ai combattu, {foes} {foes=a|a|ont|ont} mérité une seconde pensée, et l'{foes=a|a|ont|ont} eue.",
        [3] = "J'ai fini par avoir raison de {foes}, à un prix que je compte bien ne jamais payer deux fois.",
        [4] = "{foes} sont {foes=tombés|tombées|tombés|tombées} sous mes coups tour à tour, et je n'ai gaspillé aucune pitié.",
        [5] = "Je me suis $gmesuré:mesurée; à {foes}, et aucun ne m'a donné de raison de douter de l'issue.",
        [6] = "J'ai combattu {foes}, et l'un ou l'autre a bien failli l'emporter.",
        [7] = "J'ai réglé leur sort à {foes} chacun à son tour, tous, avec plus de méthode que de drame.",
        [8] = "J'ai affronté {foes}, et l'un d'eux a bien failli m'achever, ce que je n'aime pas me rappeler.",
      },
      ["d-land"] = {
        [1] = "J'ai consacré mes premiers pas sur le sol de {lands} à apprendre où l'endroit cachait ses dangers.",
        [2] = "J'ai découvert {lands}, et je me suis $gsurpris:surprise; à repérer les abris du lieu avant toute chose.",
        [3] = "J'ai découvert {lands} la garde haute, et ma curiosité, comme d'habitude, un peu en avance sur elle.",
        [4] = "Je suis $gentré:entrée; sur les terres de {lands}, $gétranger:étrangère; dans chacune et nullement $gpressé:pressée; de cesser de l'être.",
        [5] = "J'ai traversé {lands}, chacune nouvelle pour moi, et je leur ai accordé à toutes l'étude attentive et sans hâte que j'accorde à tout ce qui m'est inconnu.",
        [6] = "J'ai découvert {lands}, et j'ai trouvé l'endroit déjà en partie à nous, si bien que l'étrangeté me pesait moins.",
      },
      ["d-react"] = {
        [1] = "Je n'ai pas grande foi en la justice, mais j'ai fait une exception pour celui-là.",
        [2] = "Quoi que celui-là ait voulu faire du monde, le monde devrait s'en passer.",
        [3] = "Je ne m'attendais pas à ce que les vivants me confient leur vie, et je me suis $gaperçu:aperçue; que je ne voulais pas les décevoir.",
        [4] = "Accompagner quelqu'un sain et sauf jusqu'au bout était une étrange mission pour quelqu'un de mon espèce, et qui ne me déplaisait pas.",
        [5] = "Le Fléau m'a pris ma première vie, et chacun de ses serviteurs que j'abats est une dette que je suis $gheureux:heureuse; de recouvrer.",
        [6] = "Ils étaient morts comme je suis $gmort:morte;, et toujours au service d'un Roi-liche, ce que je ne suis plus. Je n'ai ressenti aucune parenté avec eux.",
        [7] = "Je sais ce que c'est que d'être $gchangé:changée; en autre chose, et j'espérais que la fin était venue comme une grâce.",
      },
      ["d-spec"] = {
        [1] = "J'avais choisi la voie des [[spec:Arms]], un métier de soldat dont les morts de Lordaeron se souviennent mieux que ses vivants ne l'ont jamais fait.",
        [2] = "J'avais choisi la [[spec:Fury]], et découvert qu'un corps mort pouvait contenir plus de colère que je ne l'aurais cru.",
        [3] = "J'avais choisi la [[spec:Protection]], et je me tiendrais devant les vivants s'il le fallait, ce qui ne manque pas d'ironie.",
        [4] = "J'avais choisi l'[[spec:Assassination]], les poisons de la Société royale des apothicaires étant bien trop bons pour rester dans leurs flacons.",
        [5] = "J'avais choisi le [[spec:Combat]], rapide et sans grâce, et découvert qu'il ne me restait aucune dignité qui s'en offusque.",
        [6] = "J'avais choisi la [[spec:Subtlety]]. Passer $ginaperçu:inaperçue; parmi les vivants me venait plus facilement que cela ne le devrait.",
        [7] = "J'avais choisi la [[spec:Discipline]], une foi de la volonté sur la chair, qui convenait à une chair comme la mienne.",
        [8] = "Je m'étais $gvoué:vouée; à la voie du [[spec:Holy]], en sachant que la Lumière me brûlerait chaque fois que je l'invoquerais pour autrui.",
        [9] = "Je m'étais $gtourné:tournée; vers l'[[spec:Shadow]], qui ne me demandait rien que la tombe ne m'ait déjà appris.",
        [10] = "J'avais consacré mes études aux [[spec:Arcane]], le vieil art des tours de Dalaran, que plus d'un à [[Undercity]] a appris dans sa première vie.",
        [11] = "J'avais consacré mes études au [[spec:Fire]], sans jamais oublier ce que le feu fait à une vieille chair desséchée.",
        [12] = "J'avais consacré mes études au [[spec:Frost]], le froid de la tombe enfin mis à profit.",
        [13] = "J'avais choisi l'[[spec:Affliction]], des malédictions qui pourrissent et dessèchent, et je ne pouvais pas prétendre qu'elles me semblaient étrangères.",
        [14] = "J'avais choisi la [[spec:Demonology]], et trouvé les démons guère plus inquiétants que le maître qu'on m'avait jadis $gforcé:forcée; à servir.",
        [15] = "J'avais choisi la [[spec:Destruction]], assez de feu pour rappeler au Fléau ce qu'il avait fait à Lordaeron.",
        [16] = "J'ai abandonné {was} pour {spec}. Changer ce que je suis, j'en ai une certaine habitude.",
        [17] = "{was} m'avait $gservi:servie;, mais la mort m'avait appris combien peu de choses sont permanentes, et j'ai adopté {spec}.",
      },
      ["died"] = {
        [1] = "{foe} m'a $gtué:tuée; {at}, ce qui n'a rien fait pour améliorer mon opinion des secondes funérailles.",
        [2] = "Je suis $gtombé:tombée; sous les coups de {foe} {at}. Apparemment, le monde jugeait qu'une seule mort ne suffisait pas.",
        [3] = "J'ai fait une chute mortelle {at}, et le sol était aussi dur qu'il l'avait toujours été.",
        [4] = "Je me suis $gnoyé:noyée; {at}, une fin particulièrement insultante pour qui n'avait guère besoin de respirer.",
        [5] = "Je suis $gmort:morte; {at}, avec le sentiment d'avoir été $gprivé:privée; de l'avenir que Sylvanas m'avait rendu.",
        [6] = "Je suis $gmort:morte; {at}. Une tombe familière n'était toujours pas un endroit où je voulais retourner.",
        [7] = "Le feu m'a $gtué:tuée; {at}, et $gmort:morte; ou non, je n'avais aucune défense contre lui.",
        [8] = "Je suis $gmort:morte; {at}. Le monde avait trouvé moyen de me tuer sans même fournir un ennemi à qui en vouloir.",
        [9] = "{foe} m'a $gtué:tuée; {at}, et j'ai regretté d'avoir laissé à quelqu'un d'autre le dernier mot sur ma dépouille.",
        [10] = "Je suis $gmort:morte; {at}, et mourir de nouveau n'était pas plus facile à accepter que je ne l'avais imaginé pour la première fois.",
      },
      ["mount"] = {
        [1] = "J'ai monté {mount=mon|ma|mes|mes} {mount} pour la première fois, un cheval aussi mort que moi et tout aussi peu disposé à s'arrêter.",
        [2] = "{mount=Mon|Ma|Mes|Mes} {mount} ne se fatiguait jamais et ne se plaignait jamais, et j'ai découvert que j'appréciais les deux.",
        [3] = "Les chevaux des vivants s'écartent de mon espèce, mais {mount=mon|ma|mes|mes} {mount} n'avait pas de telles opinions.",
      },
      ["night"] = {
        [1] = "Je me suis $garrêté:arrêtée; dehors {at}, sans aucune envie de faire de cette pause un arrangement permanent.",
        [2] = "J'ai passé une nuit de plus à la belle étoile {at}. Un toit aurait été le bienvenu, mais j'avais connu de pires logis.",
        [3] = "Je me suis $gallongé:allongée; {at}, par une habitude que la mort n'avait pas tout à fait réussi à guérir.",
      },
      ["opening"] = {
        [1] = "J'ai repris la route {at}, avec moins de souffle qu'$gun aventurier vivant:une aventurière vivante; et pas mal d'affaires inachevées.",
        [2] = "Le cimetière pouvait bien attendre son bien. J'ai repris la route {at}.",
        [3] = "Je me suis $gmis:mise; en route {at}, $gprêt:prête; pour les regards habituels et bien $gdécidé:décidée; à être utile malgré tout.",
        [4] = "Mon utilité, je l'espérais, me présenterait {at} avant mon odeur.",
        [5] = "J'ai commencé cette étape {at}, refusant de gaspiller à rester immobile la liberté que Sylvanas avait gagnée.",
        [6] = "Un corps mort et une aversion bien vivante pour les ordres : j'ai sorti les deux {at}.",
        [7] = "J'ai continué {at}, en me rappelant les fermes de Lordaeron telles qu'elles étaient avant la peste, ce qui était la façon la plus douce de s'en souvenir.",
        [8] = "Garder mes pensées pour moi était une habitude que [[Undercity]] encourageait, et je l'ai gardée {at}.",
        [9] = "J'ai repris la route {at}, assez en forme pour le travail et cultivant une saine rancune envers l'expression « en bonne santé ».",
        [10] = "Le monde n'avait pas été arrangé pour les gens de mon espèce, mais je suis $gparti:partie; {at} avec l'intention d'en faire bon usage malgré tout.",
        [11] = "Les plus anciens membres de la Horde et ses plus récents s'habituaient encore les uns aux autres, et j'ai continué {at} parmi les plus récents.",
        [12] = "La nuit était tombée {at}, et je suis $gparti:partie;, ayant appris à la préférer pour ses routes tranquilles et ses conversations brèves.",
        [13] = "Aucune troisième vie ne suivrait cette seconde, et je suis $gparti:partie; {at} avec cette pensée bien en tête.",
        [14] = "J'ai repris la route {at}, bien loin du jour où, à [[Deathknell]], je m'étais pour la première fois demandé ce qu'il restait de moi.",
        [15] = "Du travail m'attendait {at}, et la nouveauté d'y aller de mon propre choix ne s'était pas encore usée.",
        [16] = "La route n'avait aucune opinion sur ce que j'étais, ce qui en faisait une meilleure compagnie que la plupart, et je l'ai reprise {at}.",
        [17] = "La journée a commencé {at}, et je l'ai abordée $gprêt:prête; à être agréablement $gsurpris:surprise; et pleinement $géquipé:équipée; pour l'autre genre de surprise.",
        [18] = "Aussi $gcourtois:courtoise; que quiconque l'était avec moi et guère plus, j'ai commencé {at}.",
        [19] = "Je suis $gparti:partie; {at} en plein jour, que je supporte bien mieux que ne le prétendent les histoires sur les morts.",
        [20] = "L'obscurité couvrait {where}, et mes propres yeux étaient la seule vigie à laquelle je croyais tout à fait.",
        [21] = "La [[faction:Scarlet Crusade]] convoitait toujours le sol {at} et ne l'aurait jamais, et j'ai repris le travail.",
        [22] = "J'ai continué {at}, demandant peu à une terre qui ne me devait rien.",
        [23] = "Il y avait du travail à prendre {at}, et j'y suis $gallé:allée; la tête claire, avec une courte liste de gens en qui j'avais confiance.",
        [24] = "La curiosité m'a $gmis:mise; en mouvement {at} bien avant le sens du devoir, et j'ai été $gcontent:contente; de la laisser mener.",
        [25] = "Des plans avaient fait échouer des royaumes entiers de mon vivant, alors je suis $gparti:partie; {at} avec un plan modeste, tenu sans trop serrer.",
        [26] = "Je suis $gparti:partie; {at}, sceptique envers le travail facile et en espérant discrètement en trouver.",
      },
      ["rest"] = {
        [1] = "Je me suis $greposé:reposée; {at}, $greconnaissant:reconnaissante; de rester $gallongé:allongée; sans qu'on cloue un couvercle au-dessus de moi.",
        [2] = "Le sommeil ne m'était pas nécessaire, mais l'arrêt l'était, et je me suis $garrêté:arrêtée; {at}.",
        [3] = "La paix {at} n'avait rien de permanent, et cela me convenait.",
        [4] = "Je me suis $greposé:reposée; {at}, aussi immobile que je l'avais été dans la terre de Lordaeron, et en bien meilleure compagnie.",
        [5] = "Le silence s'est posé sur moi {at} aussi uniformément que la poussière dans une pièce fermée.",
        [6] = "Je suis $gresté:restée; immobile {at}, le sommeil me manquant bien plus que je n'en avais besoin.",
        [7] = "Mes articulations se sont tassées {at} comme les lattes d'une maison vide.",
        [8] = "Aucune voix de maître dans ma tête {at} pour faire de l'immobilité un crime, et je me suis $greposé:reposée;.",
        [9] = "Je me suis $greposé:reposée; {at}, en pensant aux toits de guingois de [[Brill]] avec quelque chose comme de la tendresse.",
        [10] = "Rien ne m'était demandé {at}, et personne n'avait le droit de le demander.",
        [11] = "Les courses du jour pouvaient attendre. Je me suis $garrêté:arrêtée; {at}, ayant appris que la plupart des choses se gardent plus longtemps qu'on ne le croit.",
        [12] = "Je me suis $ginstallé:installée; {at}, et je me suis accordé le luxe rare de baisser ma garde.",
        [13] = "Je me suis $gassis:assise; près du feu {at}, assez loin pour en profiter sans en devenir une partie.",
        [14] = "Rester immobile n'avait jamais été le problème. Je me suis $gassis:assise; {at}, $gcontent:contente; simplement qu'on me laisse en paix pendant ce temps.",
        [15] = "Je me suis $gattardé:attardée; {at}, et j'ai laissé les agacements du jour sombrer hors de vue comme tout ce qu'on lâche dans les canaux de [[Undercity]].",
        [16] = "Être $gcompté:comptée; parmi la Horde me semblait encore étrange, et je me suis $ginstallé:installée; {at} à y réfléchir sans parvenir à un verdict.",
        [17] = "Les flammes {at} ont eu droit à l'attention que je réserve d'habitude aux inconnus sur lesquels je ne me suis pas encore fait d'avis.",
        [18] = "L'étape était finie {at}. Ce qui restait pouvait m'attendre ou trouver quelqu'un de plus empressé.",
        [19] = "Je me suis $gassis:assise; {at}, à repasser en revue les gens à qui j'avais eu affaire et ceux avec qui je traiterais volontiers de nouveau.",
      },
      ["riding"] = {
