        [2] = "J'ai posé le sabot sur le sol de {lands} pour la première fois, et la terre y était différente sous moi d'une façon que je ne savais pas encore nommer.",
        [3] = "J'ai découvert {lands}, et je me suis demandé qui avait foulé ce sol le premier, et s'il l'avait foulé avec douceur.",
