        [5] = "J'ai découvert {lands}, en gardant à l'esprit que d'autres avaient aimé ce sol bien avant que j'y pose les yeux.",
        [6] = "J'ai passé la frontière de {lands} pour la première fois, et j'ai trouvé à aimer dans chaque contrée, si étrange que soit le visage qu'elle me montrait.",
